fn meshgrid(x: Vec<f32>, y: Vec<f32>) -> (Vec<Vec<f32>>, Vec<Vec<f32>>) {
    let x_len = x.len();
    let y_len = y.len();
    
    // First matrix: each row is a copy of x
    let mut matrix_x = Vec::with_capacity(y_len);
    for _ in 0..y_len {
        matrix_x.push(x.clone());
    }
    
    // Second matrix: each row has len(x) elements, all equal to y[i]
    let mut matrix_y = Vec::with_capacity(y_len);
    for i in 0..y_len {
        let row = vec![y[i]; x_len];
        matrix_y.push(row);
    }
    
    (matrix_x, matrix_y)
}